package com.bank.analytics;

import java.util.logging.*;

public class MedianDemo {
    private static final Logger log = Logger.getLogger(MedianDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Sorted savings amounts and sorted current-account amounts
        int[] savings = {1000, 3000, 5000};
        int[] current = {2000, 4000};         // combined length 5 (odd)

        int[] savings2 = {1000, 3000};
        int[] current2 = {2000, 4000};        // combined length 4 (even)

        MedianAnalyzer analyzer = new MedianAnalyzer();

        log.info("Median across combined datasets (odd total count)");
        log.info("Median -> " + analyzer.findMedian(savings, current));

        log.info("Median across combined datasets (even total count)");
        log.info("Median -> " + analyzer.findMedian(savings2, current2));
    }
}

