class MedianAnalyzer {
    // Partition binary search over the smaller array. O(log(min(m,n))).
    double findMedian(int[] a, int[] b) {
        // Always binary-search the smaller array
        if (a.length > b.length) return findMedian(b, a);

        int m = a.length, n = b.length;
        int low = 0, high = m;
        int halfLen = (m + n + 1) / 2;

        while (low <= high) {
            int i = low + (high - low) / 2;   // cut in a
            int j = halfLen - i;              // derived cut in b

            int aLeftMax  = (i == 0) ? Integer.MIN_VALUE : a[i - 1];
            int aRightMin = (i == m) ? Integer.MAX_VALUE : a[i];
            int bLeftMax  = (j == 0) ? Integer.MIN_VALUE : b[j - 1];
            int bRightMin = (j == n) ? Integer.MAX_VALUE : b[j];

            if (aLeftMax <= bRightMin && bLeftMax <= aRightMin) {
                // Correct partition found
                if (((m + n) & 1) == 1) {
                    return Math.max(aLeftMax, bLeftMax);         // odd total
                } else {
                    return (Math.max(aLeftMax, bLeftMax)
                          + Math.min(aRightMin, bRightMin)) / 2.0; // even total
                }
            } else if (aLeftMax > bRightMin) {
                high = i - 1;                 // cut i too far right
            } else {
                low = i + 1;                  // cut i too far left
            }
        }
        throw new IllegalArgumentException("Input arrays are not sorted");
    }
}

